function decode(table, value) {
  const key = String(value == null ? '' : value).trim();
  if (!key) return null;
  return table[key] || null;
}

// Returns the agency's own wording where the code is known, and the raw code
// otherwise, so an unrecognised value is still shown rather than dropped.
function label(table, value) {
  const key = String(value == null ? '' : value).trim();
  if (!key) return null;
  return table[key] || key;
}

